package main
import("bytes";"encoding/json";"flag";"fmt";"net/http";"os";"strings";"time")
func main(){action:=flag.String("action","status","status|fault|clear");node:=flag.String("node","http://127.0.0.1:8081","node base URL");blocked:=flag.String("blocked","","comma-separated peer IDs to block");delay:=flag.Int("delay-ms",0,"inbound/outbound RPC delay in milliseconds");flag.Parse();base:=strings.TrimRight(*node,"/");client:=&http.Client{Timeout:2*time.Second};switch *action{case "status":resp,e:=client.Get(base+"/raft/status");if e!=nil{fatal(e)};defer resp.Body.Close();var v any;if e=json.NewDecoder(resp.Body).Decode(&v);e!=nil{fatal(e)};b,_:=json.MarshalIndent(v,"","  ");fmt.Println(string(b));case "fault","clear":bs:=[]string{};d:=*delay;if *action=="fault"&&*blocked!=""{bs=strings.Split(*blocked,",")};if *action=="clear"{d=0};body,_:=json.Marshal(map[string]any{"blocked":bs,"delay_ms":d});req,e:=http.NewRequest(http.MethodPost,base+"/raft/fault",bytes.NewReader(body));if e!=nil{fatal(e)};req.Header.Set("Content-Type","application/json");resp,e:=client.Do(req);if e!=nil{fatal(e)};defer resp.Body.Close();if resp.StatusCode>=300{fatal(fmt.Errorf("HTTP %s",resp.Status))};var v any;if e=json.NewDecoder(resp.Body).Decode(&v);e!=nil{fatal(e)};b,_:=json.MarshalIndent(v,"","  ");fmt.Println(string(b));default:fatal(fmt.Errorf("unknown action %q",*action))}}
func fatal(e error){fmt.Fprintln(os.Stderr,e);os.Exit(1)}
